window.products.push({"id":603704,"name":"Gila Heat Control 3-in-1 Adhesive Residential DIY Window Film Sun Blocking Glare Reduction 4ft x 15ft (48in x 180in), Gray","category":"homeandappliances","retail price":82.98,"sale price":null,"image":"https://m.media-amazon.com/images/I/71H8KLSyfeL._AC_SL1500_.jpg","description":"Gila 3-in-1 Heat Control Window Film is an intelligently-designed heat control window film that will transform your windows. It combines advanced heat- and glare-rejecting technologies with low-reflectivity material to create a product that is effective and nearly invisible. This adhesive-based film is engineered to provide a fast, easy installation that adheres firmly to flat glass surfaces. No need for professional installers-this film is hassle-free and perfect for DIY (Do It Yourself) projects. The film reflects UV rays while allowing in natural light and maintaining your view of the outside. It's energy-efficient, too. Blocking heat can lead to lower cooling costs and increase comfort in rooms with direct sunlight.","images":["https://m.media-amazon.com/images/I/71H8KLSyfeL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Gila","source_asin":"B07NF7ZPRK","category_path":"Home & Kitchen"},"sku":"BM-603704","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07NF7ZPRK","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07NF7ZPRK","price_pending":true,"merchant_ready":false});
